begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at)
values('50000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','replay-a@example.invalid','',now()),
('50000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','replay-b@example.invalid','',now());
create temporary table fixture_replay(label text,id uuid,lease uuid,version integer);
grant all on fixture_replay to service_role,authenticated;
select ok(not (select enabled from public.ranked_rulesets limit 1),'ranked activation closed by default');
update public.ranked_rulesets set enabled=true;
set local role service_role;
insert into fixture_replay(label,id) select 'A',(public.issue_replay_run('50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','20da1845f2ea33f5c8659ec1f955a715393191228a9ac44c1dea7cc76611fcdd','phone','test')->>'id')::uuid;
select is((public.issue_replay_run('50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','20da1845f2ea33f5c8659ec1f955a715393191228a9ac44c1dea7cc76611fcdd','phone','test')->>'id')::uuid,(select id from fixture_replay where label='A'),'duplicate start returns exact run');
select throws_ok($$select public.issue_replay_run('50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','20da1845f2ea33f5c8659ec1f955a715393191228a9ac44c1dea7cc76611fcdd','desktop','test')$$,'40001',null,'conflicting start rejected');
select throws_ok($$select public.issue_replay_run('50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002','20da1845f2ea33f5c8659ec1f955a715393191228a9ac44c1dea7cc76611fcdd','phone','test')$$,'55000',null,'one active run per player');
-- A billion-step claim cannot be used as duration proof; actual actions count.
select throws_ok($$select public.submit_replay_run('50000000-0000-4000-8000-000000000001',(select id from fixture_replay where label='A'),'70000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('tick',i,'x',1,'y',1,'action','step')) from generate_series(1,18000) i))$$,'22023',null,'five-minute simulation cannot finish immediately');
reset role;
update public.ranked_replay_runs set started_at=clock_timestamp()-interval '1 second' where id=(select id from fixture_replay where label='A');
set local role service_role;
select is(public.submit_replay_run('50000000-0000-4000-8000-000000000001',(select id from fixture_replay where label='A'),'70000000-0000-4000-8000-000000000001','[{"tick":1,"x":100,"y":100,"action":"step"}]')->>'status','processing','finish queues durable telemetry');
select is(public.submit_replay_run('50000000-0000-4000-8000-000000000001',(select id from fixture_replay where label='A'),'70000000-0000-4000-8000-000000000001','[{"tick":1,"x":100,"y":100,"action":"step"}]')->>'status','processing','same finish retries idempotently');
select throws_ok($$select public.submit_replay_run('50000000-0000-4000-8000-000000000001',(select id from fixture_replay where label='A'),'70000000-0000-4000-8000-000000000001','[{"tick":1,"x":200,"y":100,"action":"step"}]')$$,'40001',null,'changed retry never replaces telemetry');
select throws_ok($$select public.submit_replay_run('50000000-0000-4000-8000-000000000002',(select id from fixture_replay where label='A'),'70000000-0000-4000-8000-000000000002','[{"tick":1,"x":100,"y":100,"action":"step"}]')$$,'42501',null,'other actor cannot submit run');
with job as(select public.claim_replay_run() as data) update fixture_replay set lease=(job.data->>'lease_nonce')::uuid,version=(job.data->>'lease_version')::integer from job where label='A';
select is(public.claim_replay_run(),null::jsonb,'live lease cannot be double-claimed');
select is(public.complete_replay_run((select id from fixture_replay where label='A'),gen_random_uuid(),1,99),false,'wrong worker fence cannot commit');
select is(public.complete_replay_run((select id from fixture_replay where label='A'),(select lease from fixture_replay where label='A'),null,99),false,'null worker version cannot bypass fence');
reset role;
update public.ranked_replay_runs set lease_until=clock_timestamp()-interval '1 second' where id=(select id from fixture_replay where label='A');
set local role service_role;
create temporary table old_lease as select * from fixture_replay;
with job as(select public.claim_replay_run() as data) update fixture_replay set lease=(job.data->>'lease_nonce')::uuid,version=(job.data->>'lease_version')::integer from job where label='A';
select is((select version from fixture_replay where label='A'),2,'crashed worker reclaimed with new fence');
select is(public.complete_replay_run((select id from old_lease),(select lease from old_lease),(select version from old_lease),99),false,'stale worker cannot publish');
select is(public.complete_replay_run((select id from fixture_replay),(select lease from fixture_replay),(select version from fixture_replay),1),true,'current worker may finalize replay');
select is(public.complete_replay_run((select id from fixture_replay),(select lease from fixture_replay),(select version from fixture_replay),1),true,'worker commit retry is idempotent');
select is(public.complete_replay_run((select id from fixture_replay),(select lease from fixture_replay),(select version from fixture_replay),999),false,'worker retry cannot replace accepted score');
reset role;
select is((select count(*) from public.ranked_telemetry),1::bigint,'one immutable telemetry row');
select is((select duration_ms from public.ranked_replay_runs where id=(select id from fixture_replay)),(select floor(extract(epoch from(finished_at-started_at))*1000)::bigint from public.ranked_replay_runs where id=(select id from fixture_replay)),'duration is generated from server timestamps');
select ok((select duration_ms>=simulated_ms from public.ranked_replay_runs where id=(select id from fixture_replay)),'accepted result satisfies elapsed-time bound');
select ok(not has_table_privilege('service_role','public.ranked_replay_runs','UPDATE'),'service uses fenced RPC rather than direct score writes');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000001',true);
select is((select count(id) from public.ranked_replay_runs),1::bigint,'owner sees run summary');
select throws_ok($$select inputs from public.ranked_telemetry$$,'42501',null,'raw telemetry private');
select throws_ok($$select public.claim_replay_run()$$,'42501',null,'player cannot claim worker');
select throws_ok($$select public.complete_replay_run(gen_random_uuid(),gen_random_uuid(),1,999)$$,'42501',null,'player cannot approve scores');
select throws_ok($$select public.issue_replay_run('50000000-0000-4000-8000-000000000001',gen_random_uuid(),'20da1845f2ea33f5c8659ec1f955a715393191228a9ac44c1dea7cc76611fcdd','phone','test')$$,'42501',null,'direct ticket SQL unavailable');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select is((select count(id) from public.ranked_replay_runs),0::bigint,'other player sees no run');
reset role;
select * from finish();
rollback;
